    READ_IN_MUTABLE_PARAMS;
    [[maybe_unused]] const std::uint64_t aNonceWordA = TwistMix64::DiffuseA(pNonce * 0xA2F6D4511EDDFD8FULL + 0x9C9CB2AE48D529C5ULL);
    [[maybe_unused]] const std::uint64_t aNonceWordB = TwistMix64::DiffuseB(pNonce * 0xC1482E4570E8B33FULL + 0xDFDC7EDF5E993002ULL);
