            aOrbiterK = ((aWandererB + RotL64(aScatter, 51U)) + 0x8205778EE0795964ULL) + aTwistOrbiterAssignSaltA[((aIndex + 13U)) & S_SALT1];
            aOrbiterA = (((aWandererJ + RotL64(aCross, 29U)) + RotL64(aCarry, 3U)) + 0x7542BA44F21BF377ULL) + aTwistOrbiterAssignSaltE[((aIndex + 16U)) & S_SALT1];
            aOrbiterD = ((aWandererI + RotL64(aPrevious, 13U)) + RotL64(aCarry, 37U)) + 0x733F8E8C528C342DULL;
            //
