            aCross = (RotL64(aWoodLaneC[((S_BLOCK1 - aIndex + 4194U)) & S_BLOCK1], 22U) ^ RotL64(aWoodLaneD[((S_BLOCK1 - aIndex + 2160U)) & S_BLOCK1], 41U));
