            //
            aOrbiterE = ((aWandererA + RotL64(aCross, 29U)) + 0x951A9C8D4351D198ULL) + aTwistOrbiterAssignSaltF[((aIndex + 7U)) & S_SALT1];
            aOrbiterF = (((aWandererH + RotL64(aIngress, 41U)) + RotL64(aCarry, 27U)) + 0x4056A22FE69036BAULL) + aTwistOrbiterAssignSaltE[(((31U - aIndex) + 27U)) & S_SALT1];
            aOrbiterA = ((aWandererB + RotL64(aPrevious, 3U)) + RotL64(aCarry, 5U)) + 0xEF8764B9D716B712ULL;
            aOrbiterH = (aWandererE + RotL64(aScatter, 13U)) + 0x1C284048A5A8E03EULL;
            aOrbiterJ = ((aWandererK + RotL64(aCross, 50U)) + RotL64(aCarry, 51U)) + 0x96D8E5C72622D851ULL;
            aOrbiterB = (aWandererF + RotL64(aScatter, 35U)) + 0xBBC906348550C202ULL;
            aOrbiterG = (aWandererJ + RotL64(aIngress, 19U)) + 0xADB4A0D8769E1655ULL;
            //
            aOrbiterE = ((aOrbiterE + aOrbiterF) + 0xA8D31F46E3DE7A78ULL) + aTwistOrbiterUpdateSaltA[((aIndex + 20U)) & S_SALT1];
