            aOrbiterA = RotL64((aOrbiterA * 0x9DAA59B82C367C4BULL), 57U);
            //
            aOrbiterH = ((aOrbiterH + aOrbiterE) + 0xA102E59284C57241ULL) + aTwistOrbiterUpdateSaltF[(((31U - aIndex) + 17U)) & S_SALT1];
            aOrbiterJ = (aOrbiterJ ^ aOrbiterH) ^ 0x8128ACFCED3A9FD5ULL;
