            aOrbiterA = RotL64((aOrbiterA * 0xB31A137169204779ULL), 53U);
            //
            aOrbiterK = (aOrbiterK + aOrbiterG) + 0x643AC766E8BAE243ULL;
            aOrbiterJ = (aOrbiterJ ^ aOrbiterK) ^ 0xAF2E027E4941859DULL;
