            aWandererD = aWandererD + ((RotL64(aIngress, 3U) + RotL64(aOrbiterA, 57U)) + aOrbiterC);
            aWandererK = aWandererK ^ ((RotL64(aScatter, 60U) + aOrbiterA) + RotL64(aOrbiterE, 53U));
            aWandererC = aWandererC + ((RotL64(aCross, 35U) + RotL64(aOrbiterE, 13U)) + aOrbiterI);
            aWandererI = aWandererI ^ (((RotL64(aIngress, 29U) + RotL64(aOrbiterC, 39U)) + aOrbiterG) + aTwistWandererUpdateSaltF[((aIndex + 26U)) & S_SALT1]);
