            aOrbiterF = ((aWandererF + RotL64(aPrevious, 38U)) + RotL64(aCarry, 35U)) + 0xE85F5B3CE9DD7138ULL;
            aOrbiterA = ((aWandererC + RotL64(aCross, 23U)) + RotL64(aCarry, 3U)) + 0x463A8396AA3B05B6ULL;
            aOrbiterB = ((aWandererJ + RotL64(aScatter, 3U)) + 0x3A1F336AB1AC16B3ULL) + aKeyRotateAOrbiterAssignSaltF[(((31U - aIndex) + 18U)) & S_SALT1];
