            aOrbiterJ = (aWandererD + RotL64(aPrevious, 12U)) + 0x203D98DD07A7A6E5ULL;
            aOrbiterG = ((aWandererA + RotL64(aIngress, 43U)) + RotL64(aCarry, 43U)) + 0x99A12BD8A2DE885FULL;
            //
            aOrbiterH = ((aOrbiterH + aOrbiterK) + 0x5D1D6EF71487995EULL) + aKeyRotateAOrbiterUpdateSaltA[(((31U - aIndex) + 29U)) & S_SALT1];
            aOrbiterD = (aOrbiterD ^ aOrbiterH) ^ 0x9B7B434D7BC2D220ULL;
