            //
            aOrbiterD = ((aOrbiterD + aOrbiterF) + 0xC1A3E808EF4D4C91ULL) + aKeyRotateAOrbiterUpdateSaltE[(((31U - aIndex) + 23U)) & S_SALT1];
            aOrbiterA = (aOrbiterA ^ aOrbiterD) ^ 0x50D22CC97CEE55FBULL;
            aOrbiterA = RotL64((aOrbiterA * 0x8F2D2741CEE3640BULL), 37U);
            //
            aOrbiterB = (aOrbiterB + aOrbiterE) + 0x2AB5F47E3C7E3AB6ULL;
