            aOrbiterF = ((aOrbiterF ^ aOrbiterK) ^ 0xC711A2DF90F106A0ULL) ^ aKeyRotateAOrbiterUpdateSaltB[(((31U - aIndex) + 11U)) & S_SALT1];
            aOrbiterF = RotL64((aOrbiterF * 0x86A1C28523C786BDULL), 5U);
            //
