            aIngress = aIngress + (aOrbiterA ^ RotL64(aOrbiterK, 3U));
            aIngress = aIngress + (aOrbiterB ^ RotL64(aOrbiterD, 51U));
            aIngress = aIngress + RotL64(aOrbiterG, 57U);
            aIngress = TwistMix64::DiffuseC((aIngress + aScatter));
            //
            aWandererK = aWandererK + ((RotL64(aIngress, 19U) + RotL64(aOrbiterK, 13U)) + aOrbiterJ);
            aWandererJ = aWandererJ ^ ((RotL64(aScatter, 56U) + aOrbiterK) + RotL64(aOrbiterC, 60U));
            aWandererB = aWandererB + (((RotL64(aCross, 27U) + aOrbiterH) + RotL64(aOrbiterF, 23U)) + RotL64(aCarry, 23U));
            aWandererG = aWandererG ^ (((RotL64(aPrevious, 35U) + aOrbiterE) + RotL64(aOrbiterK, 35U)) + aKeyRotateAWandererUpdateSaltB[((aIndex + 22U)) & S_SALT1]);
            aWandererH = aWandererH + ((RotL64(aIngress, 39U) + RotL64(aOrbiterI, 19U)) + aOrbiterH);
            aWandererE = aWandererE ^ ((RotL64(aCross, 3U) + aOrbiterB) + RotL64(aOrbiterK, 53U));
            aWandererD = aWandererD + ((RotL64(aPrevious, 22U) + RotL64(aOrbiterF, 47U)) + aOrbiterC);
            aWandererC = aWandererC ^ ((RotL64(aScatter, 29U) + aOrbiterA) + RotL64(aOrbiterG, 26U));
            aWandererF = aWandererF + ((RotL64(aCross, 5U) + aOrbiterA) + RotL64(aOrbiterD, 11U));
            aWandererI = aWandererI ^ ((RotL64(aPrevious, 47U) + RotL64(aOrbiterF, 37U)) + aOrbiterA);
            aWandererA = aWandererA + ((((RotL64(aScatter, 11U) + aOrbiterI) + RotL64(aOrbiterA, 5U)) + RotL64(aCarry, 5U)) + aKeyRotateAWandererUpdateSaltE[(((31U - aIndex) + 11U)) & S_SALT1]);
