            aScatter = TwistMix64::DiffuseB((aScatter ^ aKeyRotateADomainWordScatter));
            //
            aOrbiterK = (aWandererI + RotL64(aScatter, 13U)) + 0xBF74345C88F5958FULL;
            aOrbiterF = (aWandererJ + RotL64(aCross, 27U)) + 0xC22DB405CE419573ULL;
            aOrbiterG = ((aWandererB + RotL64(aPrevious, 35U)) + RotL64(aCarry, 39U)) + 0xF898294E8156C375ULL;
