            aOrbiterI = (((aWandererK + RotL64(aScatter, 60U)) + RotL64(aCarry, 53U)) + 0x999388E96162F193ULL) + aKeyRotateAOrbiterAssignSaltA[((aIndex + 3U)) & S_SALT1];
