            aOrbiterH = (aWandererC + RotL64(aIngress, 5U)) + 0xEA978A2BBF85CA65ULL;
            //
            aOrbiterK = ((aOrbiterK + aOrbiterF) + 0x47D022C277CDA891ULL) + aKeyRotateAOrbiterUpdateSaltF[(((31U - aIndex) + 18U)) & S_SALT1];
            aOrbiterG = (aOrbiterG ^ aOrbiterK) ^ 0x39567C7AC46F1416ULL;
