            aOrbiterJ = (aOrbiterJ + aOrbiterG) + 0xA1F983F3F3378B96ULL;
            aOrbiterI = (aOrbiterI ^ aOrbiterJ) ^ 0xE266A5FA72D93432ULL;
            aOrbiterI = RotL64((aOrbiterI * 0x3909C750FCEFE0ADULL), 37U);
