            aOrbiterE = ((aOrbiterE + aOrbiterK) + 0xB5112A3B8BA5CF96ULL) + aKeyRotateAOrbiterUpdateSaltB[(((31U - aIndex) + 19U)) & S_SALT1];
            aOrbiterJ = ((aOrbiterJ ^ aOrbiterE) ^ 0x0B3EFCDCB426729DULL) ^ aKeyRotateAOrbiterUpdateSaltD[((aIndex + 8U)) & S_SALT1];
            aOrbiterJ = RotL64((aOrbiterJ * 0xFC1681DB9D8BCF9DULL), 23U);
