            aOrbiterF = (aOrbiterF + aOrbiterJ) + 0x9CAF6666E9325776ULL;
            aOrbiterH = (aOrbiterH ^ aOrbiterF) ^ 0x4314D16350A76A75ULL;
            aOrbiterH = RotL64((aOrbiterH * 0xAAE5DAF85C371A9FULL), 5U);
            //
            aOrbiterH = (aOrbiterH + aOrbiterI) + 0x8130454343C55C77ULL;
            aOrbiterK = (aOrbiterK ^ aOrbiterH) ^ 0xE572E36DAFA4B999ULL;
            aOrbiterK = RotL64((aOrbiterK * 0xE6B379B0568512F1ULL), 29U);
            //
            aOrbiterG = ((aOrbiterG + aOrbiterH) + 0x586679BDD32CBB9CULL) + aKeyRotateAOrbiterUpdateSaltC[(((31U - aIndex) + 22U)) & S_SALT1];
            aOrbiterE = (aOrbiterE ^ aOrbiterG) ^ 0x22276E98A3C973A9ULL;
            aOrbiterE = RotL64((aOrbiterE * 0x6CA527ABAEA49B33ULL), 57U);
            //
            aOrbiterI = (aOrbiterI + aOrbiterE) + 0xAA98FAD20ECAF8A1ULL;
            aOrbiterF = (aOrbiterF ^ aOrbiterI) ^ 0x742E7DB8854EC2F6ULL;
            aOrbiterF = RotL64((aOrbiterF * 0x702B4A3CAC458E45ULL), 11U);
            //
            aIngress = RotL64(aOrbiterG, 54U) ^ aOrbiterF;
