            aWandererK = aWandererK + (((RotL64(aCross, 21U) + RotL64(aOrbiterE, 11U)) + aOrbiterK) + RotL64(aCarry, 51U));
            aWandererI = aWandererI ^ ((RotL64(aScatter, 54U) + RotL64(aOrbiterI, 29U)) + aOrbiterK);
            aWandererC = aWandererC + (((RotL64(aPrevious, 11U) + RotL64(aOrbiterE, 21U)) + aOrbiterG) + RotL64(aCarry, 29U));
