            aWandererJ = aWandererJ + (((RotL64(aScatter, 3U) + aOrbiterE) + RotL64(aOrbiterJ, 35U)) + aKeyRotateAWandererUpdateSaltF[(((31U - aIndex) + 7U)) & S_SALT1]);
            aWandererE = aWandererE ^ ((RotL64(aIngress, 43U) + aOrbiterF) + RotL64(aOrbiterK, 57U));
            aWandererB = aWandererB + ((RotL64(aCross, 29U) + RotL64(aOrbiterG, 51U)) + aOrbiterH);
