            aPrevious = aIngress;
            //
            aIngress = (RotL64(aFuseLaneB[((aIndex + 22944U)) & S_BLOCK1], 5U) ^ RotL64(aWindLaneD[((aIndex + 21920U)) & S_BLOCK1], 27U));
            aIngress ^= (RotL64(aMagmaLaneD[((aIndex + 20538U)) & S_BLOCK1], 51U) ^ RotL64(aShadowLaneC[((S_BLOCK1 - aIndex + 17173U)) & S_BLOCK1], 60U));
            aIngress = TwistMix64::DiffuseB((aIngress ^ aKeyRotateADomainWordIngress));
            //
            aCross = (RotL64(aFuseLaneA[((S_BLOCK1 - aIndex + 24559U)) & S_BLOCK1], 21U) ^ RotL64(aWindLaneB[((S_BLOCK1 - aIndex + 21195U)) & S_BLOCK1], 35U));
            aCross ^= (RotL64(aShadowLaneB[((S_BLOCK1 - aIndex + 23667U)) & S_BLOCK1], 10U) ^ RotL64(aPoisonLaneA[((aIndex + 20401U)) & S_BLOCK1], 51U));
            aCross = TwistMix64::DiffuseB((aCross ^ aKeyRotateADomainWordCross));
            //
            aScatter = (RotL64(aCross, 21U) + RotL64(aIngress, 35U)) ^ (RotL64(aPrevious, 50U) + RotL64(aCarry, 5U));
            aScatter = TwistMix64::DiffuseB((aScatter ^ aKeyRotateADomainWordScatter));
            //
            aOrbiterJ = ((aWandererG + RotL64(aPrevious, 24U)) + RotL64(aCarry, 51U)) + 0x9A821213BC194B33ULL;
            aOrbiterB = ((aWandererH + RotL64(aCross, 35U)) + 0xF3F4EF7A597A74EAULL) + aKeyRotateAOrbiterAssignSaltB[((aIndex + 24U)) & S_SALT1];
            aOrbiterE = ((aWandererI + RotL64(aScatter, 57U)) + RotL64(aCarry, 21U)) + 0x904896A9AD6E19EDULL;
            aOrbiterF = (aWandererK + RotL64(aIngress, 41U)) + 0xAF6D57CCE63768E5ULL;
            aOrbiterC = (aWandererE + RotL64(aCross, 51U)) + 0x7D6547DD9E950C87ULL;
            aOrbiterH = (((aWandererA + RotL64(aIngress, 13U)) + RotL64(aCarry, 37U)) + 0x8F2C1213F8E088CDULL) + aKeyRotateAOrbiterAssignSaltC[(((31U - aIndex) + 11U)) & S_SALT1];
            aOrbiterG = (aWandererF + RotL64(aScatter, 5U)) + 0x9398F695633517BFULL;
            //
            aOrbiterJ = ((aOrbiterJ + aOrbiterB) + 0xA33F035D65627C98ULL) + aKeyRotateAOrbiterUpdateSaltF[(((31U - aIndex) + 17U)) & S_SALT1];
            aOrbiterE = (aOrbiterE ^ aOrbiterJ) ^ 0xA7678EB301247CEAULL;
            aOrbiterE = RotL64((aOrbiterE * 0x42DE3AC550511FD7ULL), 43U);
            //
            aOrbiterF = (aOrbiterF + aOrbiterJ) + 0x2A4C8295F65B54DBULL;
            aOrbiterB = (aOrbiterB ^ aOrbiterF) ^ 0x893A2AFEEB3A8FD7ULL;
            aOrbiterB = RotL64((aOrbiterB * 0x1FD876CD927308F3ULL), 21U);
            //
            aOrbiterC = (aOrbiterC + aOrbiterH) + 0x85C514B996907CF1ULL;
            aOrbiterF = (aOrbiterF ^ aOrbiterC) ^ 0xA5A2B6A756BF4A2BULL;
            aOrbiterF = RotL64((aOrbiterF * 0x91A612ED488F45BBULL), 37U);
            //
            aOrbiterG = ((aOrbiterG + aOrbiterC) + 0x2A69773E5D8A8566ULL) + aKeyRotateAOrbiterUpdateSaltB[(((31U - aIndex) + 29U)) & S_SALT1];
            aOrbiterH = (aOrbiterH ^ aOrbiterG) ^ 0xD98FD66C590A9C52ULL;
            aOrbiterH = RotL64((aOrbiterH * 0x95F22B036E5AD6A3ULL), 29U);
            //
            aOrbiterH = (aOrbiterH + aOrbiterF) + 0x3725DBAF35A6B8AFULL;
            aOrbiterJ = (aOrbiterJ ^ aOrbiterH) ^ 0x330BCCB122073A9CULL;
            aOrbiterJ = RotL64((aOrbiterJ * 0xAB04E3660ECC29E7ULL), 11U);
            //
            aOrbiterE = (aOrbiterE + aOrbiterG) + 0x5F9799CED9D33BD5ULL;
            aOrbiterC = (aOrbiterC ^ aOrbiterE) ^ 0x446230ED6E5939C9ULL;
            aOrbiterC = RotL64((aOrbiterC * 0x89E4F7B389326B25ULL), 53U);
            //
            aOrbiterB = ((aOrbiterB + aOrbiterE) + 0x3B6306A4BC2394B5ULL) + aKeyRotateAOrbiterUpdateSaltE[((aIndex + 14U)) & S_SALT1];
            aOrbiterG = ((aOrbiterG ^ aOrbiterB) ^ 0x5BDD337143891785ULL) ^ aKeyRotateAOrbiterUpdateSaltD[((aIndex + 3U)) & S_SALT1];
            aOrbiterG = RotL64((aOrbiterG * 0xA93087A3F228FC51ULL), 3U);
            //
            aIngress = RotL64(aOrbiterF, 19U) ^ aOrbiterG;
            aIngress = aIngress + (RotL64(aOrbiterC, 11U) ^ aOrbiterE);
            aIngress = aIngress + (aOrbiterB ^ RotL64(aOrbiterJ, 60U));
            aIngress = aIngress + RotL64(aOrbiterH, 37U);
            aIngress = TwistMix64::DiffuseA((aIngress + aScatter));
            //
            aWandererA = aWandererA ^ (((RotL64(aCross, 19U) + RotL64(aOrbiterB, 41U)) + aOrbiterF) + aKeyRotateAWandererUpdateSaltB[(((31U - aIndex) + 19U)) & S_SALT1]);
            aWandererF = aWandererF + ((RotL64(aPrevious, 27U) + aOrbiterG) + RotL64(aOrbiterH, 26U));
            aWandererK = aWandererK ^ ((RotL64(aIngress, 50U) + aOrbiterE) + RotL64(aOrbiterJ, 19U));
            aWandererG = aWandererG + ((((RotL64(aScatter, 43U) + RotL64(aOrbiterB, 57U)) + aOrbiterJ) + RotL64(aCarry, 23U)) + aKeyRotateAWandererUpdateSaltE[((aIndex + 15U)) & S_SALT1]);
            aWandererI = aWandererI ^ ((RotL64(aCross, 3U) + aOrbiterC) + RotL64(aOrbiterF, 13U));
            aWandererE = aWandererE + (((RotL64(aIngress, 57U) + RotL64(aOrbiterH, 47U)) + aOrbiterE) + RotL64(aCarry, 39U));
            aWandererH = aWandererH ^ ((RotL64(aPrevious, 35U) + RotL64(aOrbiterG, 3U)) + aOrbiterC);
